<script>
(function(){var body=document.getElementById('ad-rows'),add=document.getElementById('add-ad'),mediaSources=@json($mediaSources),agencies=@json($advertisingAgencies),agencyMedia=@json($advertisingAgencyMedia);if(!body||!add)return;function esc(v){return String(v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}function mediaSelect(name){return '<select class="form-control input-sm ad-media" tabindex="-1" required name="'+name+'"><option value="">选择代理后自动带出</option>'+mediaSources.map(function(v){return '<option value="'+esc(v)+'">'+esc(v)+'</option>'}).join('')+'</select>'}function agencySelect(name){return '<select class="form-control input-sm ad-agency" required name="'+name+'"><option value="">请选择代理</option>'+Object.keys(agencies).map(function(v){return '<option value="'+esc(v)+'" data-coefficient="'+agencies[v]+'">'+esc(v)+'</option>'}).join('')+'</select>'}function recalc(row){var a=parseFloat((row.querySelector('.ad-spend')||{}).value)||0,b=parseFloat((row.querySelector('.ad-rate')||{}).value);if(isNaN(b))b=0;row.querySelector('.actual-spend').textContent=(a*b).toFixed(2)}body.addEventListener('change',function(e){if(e.target.classList.contains('ad-agency')){var row=e.target.closest('[data-ad-row]'),option=e.target.options[e.target.selectedIndex],rate=row.querySelector('.ad-rate'),media=row.querySelector('.ad-media'),agency=option&&option.value?option.value:'';rate.value=agency?(option.getAttribute('data-coefficient')||''):'';media.value=agency?(agencyMedia[agency]||''):'';recalc(row)}});body.addEventListener('input',function(e){var row=e.target.closest('[data-ad-row]');if(row)recalc(row)});body.addEventListener('click',function(e){var b=e.target.closest('.remove-ad');if(b)b.closest('tr').remove()});add.addEventListener('click',function(){var i=Date.now(),tr=document.createElement('tr');tr.setAttribute('data-ad-row','');tr.innerHTML='<td>'+agencySelect('ads['+i+'][agency]')+'</td><td>'+mediaSelect('ads['+i+'][media_source]')+'</td><td><input class="form-control input-sm" required name="ads['+i+'][account_name]"></td><td><input class="form-control input-sm" required name="ads['+i+'][account_number]"></td><td><input class="form-control input-sm ad-spend" required type="number" min="0" step="0.01" name="ads['+i+'][book_spend]"></td><td><input class="form-control input-sm ad-rate" required readonly type="number" min="0" step="0.0001" name="ads['+i+'][settlement_coefficient]"></td><td class="actual-spend money">0.00</td><td class="ad-image-cell"><span class="ad-image-summary"></span><input class="ad-image-input" type="file" hidden accept="image/jpeg,image/png,image/webp" name="ads['+i+'][screenshot]"><button type="button" class="btn btn-info btn-xs ad-image-open"><i class="fa fa-picture-o"></i> 上传截图</button></td><td><button type="button" class="btn btn-xs btn-danger remove-ad"><i class="fa fa-trash"></i></button></td>';body.appendChild(tr)})})();
(function(){var modal=document.getElementById('ad-image-modal'),zone=document.getElementById('ad-upload-zone'),picker=document.getElementById('ad-modal-file'),preview=document.getElementById('ad-image-preview'),error=document.getElementById('ad-upload-error'),confirm=document.getElementById('ad-image-confirm'),targetInput=null,targetCell=null,pendingFile=null,pasteActive=false;if(!modal)return;function showError(msg){error.textContent=msg;error.style.display=msg?'block':'none'}function previewUrl(url){preview.innerHTML=url?'<img src="'+url+'" alt="广告截图预览">':''}function useFile(file){showError('');if(!file||['image/jpeg','image/png','image/webp'].indexOf(file.type)<0){showError('仅支持 JPG、PNG、WEBP 图片。');return}if(file.size>5*1024*1024){showError('图片不能超过 5 MB。');return}pendingFile=file;previewUrl(URL.createObjectURL(file))}document.addEventListener('click',function(e){var open=e.target.closest&&e.target.closest('.ad-image-open');if(open){targetCell=open.closest('.ad-image-cell');targetInput=targetCell.querySelector('.ad-image-input');pendingFile=null;pasteActive=true;showError('');previewUrl(open.getAttribute('data-existing-url')||'');jQuery(modal).modal('show');return}if(e.target.closest&&e.target.closest('#ad-paste-btn')){e.preventDefault();pasteActive=true;zone.classList.add('is-paste-target');zone.focus();return}});zone.addEventListener('click',function(e){if(e.target.closest('#ad-paste-btn'))return;picker.click()});picker.addEventListener('change',function(){useFile(picker.files&&picker.files[0]);picker.value=''});zone.addEventListener('dragover',function(e){e.preventDefault();zone.classList.add('is-active')});zone.addEventListener('dragleave',function(){zone.classList.remove('is-active')});zone.addEventListener('drop',function(e){e.preventDefault();zone.classList.remove('is-active');useFile(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0])});document.addEventListener('paste',function(e){if(!pasteActive||!jQuery(modal).hasClass('in'))return;var items=(e.clipboardData||window.clipboardData).items||[];for(var i=0;i<items.length;i++){if(items[i].kind==='file'){var file=items[i].getAsFile();if(file&&file.type.indexOf('image/')===0){e.preventDefault();useFile(file);zone.classList.remove('is-paste-target');break}}}});confirm.addEventListener('click',function(){if(!pendingFile){showError('请先选择、拖拽或粘贴一张图片。');return}try{var dt=new DataTransfer();dt.items.add(pendingFile);targetInput.files=dt.files}catch(e){showError('当前浏览器不支持粘贴文件，请使用点击选择文件。');return}var url=URL.createObjectURL(pendingFile);targetCell.querySelector('.ad-image-summary').innerHTML='<img class="ad-image-thumb" src="'+url+'" alt="广告截图">';var btn=targetCell.querySelector('.ad-image-open');btn.innerHTML='<i class="fa fa-picture-o"></i> 更换截图';btn.setAttribute('data-existing-url',url);jQuery(modal).modal('hide')});jQuery(modal).on('hidden.bs.modal',function(){pasteActive=false;zone.classList.remove('is-active','is-paste-target');pendingFile=null;targetInput=null;targetCell=null;preview.innerHTML='';showError('')})})();
</script>
@endpush
